319	    @Test
320	    void ultimaPecaPagaAoMesmoTempoSoVendeUmaVez() throws Exception {
321	        List<Long> ids = new ArrayList<>();
322	        for (int i = 0; i < 6; i++) {
323	            ids.add(registrar(compra("RETIRADA_LOJA", "PIX", "BRONZE", "SUDESTE", item("MOC-001", 1))));
324	        }
325	        ExecutorService executor = Executors.newFixedThreadPool(ids.size());
326	        CountDownLatch largada = new CountDownLatch(1);
327	        List<Future<Resposta>> respostas = new ArrayList<>();
328	        for (long id : ids) {
329	            Callable<Resposta> tarefa = () -> {
330	                largada.await();
331	                return pagar(id, "TX-" + id, Instant.now());
332	            };
333	            respostas.add(executor.submit(tarefa));
334	        }
335	        largada.countDown();
336	        int pagos = 0;
337	        for (Future<Resposta> resposta : respostas) {
338	            Resposta r = resposta.get();
339	            if (r.status() == 200) {
340	                pagos++;
341	            } else {
342	                assertThat(r.status()).isEqualTo(409);
343	                assertThat(r.erro()).isEqualTo("ESTOQUE_INSUFICIENTE");
344	            }
345	        }
346	        executor.shutdown();
347	        assertThat(pagos).isEqualTo(1);
348	        assertThat(estoque("MOC-001")).isZero();
349	    }
