 13	public class TransLogFalsa {
 14	
 15	    public record Resposta(int status, String corpo, long atrasoMs) {
 16	    }
 17	
 18	    private final HttpServer servidor;
 19	    private volatile Resposta resposta;
 20	    final List<String> consultas = new CopyOnWriteArrayList<>();
 21	
 22	    public TransLogFalsa() throws IOException {
 23	        servidor = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
 24	        servidor.setExecutor(Executors.newCachedThreadPool());
 25	        servidor.createContext("/cotacao", troca -> {
 26	            consultas.add(troca.getRequestURI().getRawQuery());
 27	            Resposta atual = resposta;
 28	            try {
 29	                Thread.sleep(atual.atrasoMs());
 30	            } catch (InterruptedException e) {
 31	                Thread.currentThread().interrupt();
 32	            }
 33	            byte[] corpo = atual.corpo().getBytes(StandardCharsets.UTF_8);
 34	            troca.getResponseHeaders().add("Content-Type", "application/json");
 35	            troca.sendResponseHeaders(atual.status(), corpo.length == 0 ? -1 : corpo.length);
 36	            if (corpo.length > 0) {
 37	                troca.getResponseBody().write(corpo);
 38	            }
 39	            troca.close();
 40	        });
 41	        servidor.start();
 42	        responder(200, "{\"valor\": 33.10, \"prazoDias\": 2}");
 43	    }
 44	
 45	    public String url() {
 46	        return "http://localhost:" + servidor.getAddress().getPort();
 47	    }
 48	
 49	    public void responder(int status, String corpo) {
 50	        resposta = new Resposta(status, corpo, 0);
 51	    }
 52	
 53	    public void demorar(long atrasoMs) {
 54	        resposta = new Resposta(200, "{\"valor\": 33.10, \"prazoDias\": 2}", atrasoMs);
 55	    }
 56	}
