417	        for (String caminho : List.of("/checkout/resumo", "/pedidos")) {
418	            Resposta r = post(caminho, dados);
419	            assertThat(r.status()).as(caminho + " " + dados).isEqualTo(status);
420	            assertThat(r.erro()).as(caminho + " " + dados).isEqualTo(codigo);
421	        }
