430	    private Resposta pagar(long id, String transacao, Instant pagoEm) throws Exception {
431	        ObjectNode corpo = JSON.createObjectNode().put("idTransacao", transacao).put("pagoEm", pagoEm.toString());
432	        return post("/pedidos/" + id + "/pagamento", corpo);
433	    }
