438	
439	    private Resposta post(String caminho, JsonNode corpo) throws Exception {
440	        HttpRequest.Builder requisicao = HttpRequest.newBuilder(URI.create("http://localhost:" + porta + caminho))
441	                .header("Content-Type", "application/json");
442	        requisicao.POST(corpo == null ? HttpRequest.BodyPublishers.noBody()
443	                : HttpRequest.BodyPublishers.ofString(corpo.toString()));
444	        return enviar(requisicao.build());
445	    }
446	
447	    private Resposta get(String caminho) throws Exception {
448	        return enviar(HttpRequest.newBuilder(URI.create("http://localhost:" + porta + caminho)).GET().build());
449	    }
450	
451	    private Resposta enviar(HttpRequest requisicao) throws Exception {
452	        HttpResponse<String> resposta = http.send(requisicao, HttpResponse.BodyHandlers.ofString());
453	        String corpo = resposta.body();
454	        return new Resposta(resposta.statusCode(), corpo.isEmpty() ? JSON.createObjectNode() : JSON.readTree(corpo));
455	    }
